	/delete-property/ regulator-init-microvolt;
	regulator-always-on;
	regulator-boot-on;
	/delete-node/ regulator-state-mem;
};

&vdd_logic_s0 {
	/delete-property/ regulator-init-microvolt;
	regulator-always-on;
	regulator-boot-on;
	/delete-node/ regulator-state-mem;
};

